changeSet.sql:
DO $$
DECLARE item record; code text; number bigint;
BEGIN
    FOR item IN SELECT id FROM goods_receipt_line WHERE product_id IS NULL LOOP
        LOOP
            number := nextval('product_code_seq');
            code := 'MB-' || lpad(number::text, greatest(6, length(number::text)), '0');
            EXIT WHEN NOT EXISTS (SELECT 1 FROM product WHERE product_code = code)
                AND NOT EXISTS (SELECT 1 FROM goods_receipt_line WHERE reserved_product_code = code);
        END LOOP;
        UPDATE goods_receipt_line SET reserved_product_code = code WHERE id = item.id;
    END LOOP;
END $$;
